// Reads settings from the Set Email Processing Config node, keeps only emails from allowed senders,
// and builds one Claude request per email from its PDF attachments.
const cfg = $('Set Email Processing Config').first().json;
const allowed = String(cfg.allowedSenders || '').split(',').map(s => s.trim().toLowerCase().replace(/^@/, '')).filter(Boolean);
const vendors = String(cfg.knownVendors || '').split(',').map(s => s.trim()).filter(Boolean);

const SYSTEM = `You extract line items from vendor quotes, estimates and proposals so they can be entered into a cost estimate. Record every quote with the record_quote_lines tool. Rules:
- One line per priced item exactly as quoted. Include freight, tariff, surcharge or fee lines as their own lines when they carry a price.
- qty: number. unit_price: price per single unit as a plain number (no currency symbols or commas). If only an extended price is shown, unit_price = extended / qty. extended_price: as printed.
- description: ONE line, max ~90 characters, in the quote's own wording. Lead with the item tag if the quote gives one, then manufacturer, model/part number and key specs.
- vendor: the company that ISSUED the quote (never the bill-to or ship-to customer).${vendors.length ? ` If it matches one of these, use this exact spelling: ${vendors.join(', ')}.` : ''}
- quote_number: the quote/estimate/proposal number. quote_subtotal: the printed subtotal before tax (null if none).
- item_key: a short identifier that is IDENTICAL for equivalent items across ALL attached quotes, so the same item from different vendors can be compared. Use the item tag if one is given, else the manufacturer part/model number, else a short generic item name (e.g. "PCV-2100", "3IN-V150-VALVE").
- part_number: the manufacturer part or model number if shown, else null.
- lead_time: as written for that line; use the quote-level lead time if only one is given; null if none.
- Items listed but not priced go in not_quoted with the reason, not in lines.
- Never invent numbers. If something is unreadable, say so in notes.`;

const TOOL = {
  name: 'record_quote_lines',
  description: 'Record the line items from each attached vendor quote.',
  input_schema: { type: 'object', required: ['quotes'], properties: { quotes: { type: 'array', items: {
    type: 'object', required: ['vendor', 'lines'], properties: {
      file_name: { type: 'string' }, vendor: { type: 'string' },
      quote_number: { type: ['string', 'null'] }, quote_date: { type: ['string', 'null'] },
      quote_subtotal: { type: ['number', 'null'] },
      lines: { type: 'array', items: { type: 'object', required: ['item_key', 'qty', 'description', 'unit_price'], properties: {
        tag: { type: ['string', 'null'] }, item_key: { type: 'string' }, part_number: { type: ['string', 'null'] },
        qty: { type: 'number' }, description: { type: 'string' },
        unit_price: { type: 'number' }, extended_price: { type: ['number', 'null'] }, lead_time: { type: ['string', 'null'] } } } },
      not_quoted: { type: 'array', items: { type: 'string' } }, notes: { type: ['string', 'null'] } } } } } },
};

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const m = items[i].json;
  // Gmail (simple off) -> from.value[0].address ; Outlook raw -> from.emailAddress.address
  const addr = String(m.from?.value?.[0]?.address || m.from?.emailAddress?.address || '').toLowerCase();
  const name = m.from?.value?.[0]?.name || m.from?.emailAddress?.name || '';
  if (!addr) continue;
  if (allowed.length && !allowed.some(a => a.includes('@') ? addr === a : addr.endsWith('@' + a.replace(/^@/, '')))) continue;

  const subject = String(m.subject || '').trim();
  const jobName = subject.replace(/^\s*((re|fw|fwd)\s*:\s*)+/i, '').replace(/\s+/g, ' ').trim();

  const docs = [], pdfNames = [];
  for (const [key, bin] of Object.entries(items[i].binary || {})) {
    const fn = bin.fileName || key;
    if (!(bin.mimeType === 'application/pdf' || /\.pdf$/i.test(fn))) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    docs.push({ type: 'document', title: fn, source: { type: 'base64', media_type: 'application/pdf', data: buf.toString('base64') } });
    pdfNames.push(fn);
  }

  const base = { messageId: m.id, replyTo: addr, replyName: name, subject, jobName, pdfNames };
  if (!docs.length) { out.push({ json: { ...base, status: 'no_pdf' } }); continue; }
  out.push({ json: { ...base, status: 'ok', claudeBody: {
    model: cfg.claudeModel, max_tokens: Number(cfg.maxOutputTokens) || 8000, system: SYSTEM,
    tools: [TOOL], tool_choice: { type: 'auto' },
    messages: [{ role: 'user', content: [...docs, { type: 'text',
      text: `Attached: ${pdfNames.join(', ')}. Extract every quote's line items with record_quote_lines (one entry in quotes per PDF/quote). Respond only by calling record_quote_lines.` }] }],
  } } });
}
return out;

// Turns Claude's tool call into spreadsheet rows and checks each quote's lines against its printed subtotal.
const g = $('Loop Over Each Quote Email').first().json;
const resp = $input.first().json;
const quotes = (resp.content || []).find(c => c.type === 'tool_use')?.input?.quotes || [];
const r2 = n => Math.round((Number(n) || 0) * 100) / 100;

const rows = [], checks = [], notQuoted = [], notes = [], grouped = [];
for (const q of quotes) {
  let sum = 0;
  for (const l of q.lines || []) {
    const qty = Number(l.qty) || 0, unit = Number(l.unit_price) || 0;
    sum += qty * unit;
    rows.push({
      'Vendor': q.vendor || '', 'Quote #': q.quote_number || '', 'Quote Date': q.quote_date || '',
      'Tag': l.tag || '', 'Qty': qty, 'Description': l.description || '',
      'Unit Price': unit, 'Extended': r2(qty * unit), 'Lead Time': l.lead_time || '', 'Source File': q.file_name || '',
    });
  }
  if ((q.lines || []).length) grouped.push({ vendor: q.vendor || '', quote_number: q.quote_number || '', quote_date: q.quote_date || '',
    file_name: q.file_name || '', quote_subtotal: q.quote_subtotal ?? null, lines: q.lines, not_quoted: q.not_quoted || [], notes: q.notes || '' });
  const st = q.quote_subtotal;
  checks.push({ vendor: q.vendor, quote: q.quote_number || '', lines: (q.lines || []).length, sum: r2(sum),
                subtotal: st == null ? null : r2(st), match: st == null ? null : Math.abs(r2(sum) - r2(st)) < 0.02 });
  for (const n of q.not_quoted || []) notQuoted.push(`${q.vendor}${q.quote_number ? ' ' + q.quote_number : ''}: ${n}`);
  if (q.notes) notes.push(`${q.vendor}: ${q.notes}`);
}
const first = quotes[0] || {};
return [{ json: {
  status: rows.length ? 'ok' : 'no_lines',
  error: rows.length ? undefined : (resp.stop_reason === 'max_tokens'
    ? 'The quote was too long for the output limit; raise maxOutputTokens in the Config node.'
    : 'No priced line items were found in the attached PDF(s).'),
  jobName: g.jobName || [first.vendor, first.quote_number].filter(Boolean).join(' ') || 'Vendor Quote',
  rows, checks, notQuoted, notes, quotes: grouped,
} }];

// Builds a formatted Excel workbook with no external libraries:
// a Summary tab (live totals check) plus one formatted tab per quote.
const p = $input.first().json;   // from Verify Line Extraction or Match Items Across Quotes
const cfg = $('Set Email Processing Config').first().json;
const CUR = String(cfg.currency || 'USD');

// ---------- helpers ----------
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]))
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
const col = n => { let s = ''; for (n++; n; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + (n - 1) % 26) + s; return s; };
const num = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const r2 = n => Math.round(n * 100) / 100;
// style ids (see styles.xml below)
const S = { title: 1, sub: 2, head: 3, text: 4, wrap: 5, qty: 6, money: 7, totLabel: 8, totMoney: 9, check: 10, pct: 11 };
const cStr = (ref, v, s) => (v === '' || v === null || v === undefined) ? `<c r="${ref}" s="${s}"/>` : `<c r="${ref}" s="${s}" t="inlineStr"><is><t xml:space="preserve">${esc(v)}</t></is></c>`;
const cNum = (ref, v, s) => v === null ? `<c r="${ref}" s="${s}"/>` : `<c r="${ref}" s="${s}"><v>${v}</v></c>`;
const cF = (ref, f, cached, s, isStr) => `<c r="${ref}" s="${s}"${isStr ? ' t="str"' : ''}><f>${esc(f)}</f>${cached === null || cached === undefined ? '' : `<v>${esc(cached)}</v>`}</c>`;
const sheetXml = ({ cols, rows, merges = [], freeze, filter, cf = '' }) =>
  `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">` +
  `<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><sheetViews><sheetView workbookViewId="0">${freeze ? `<pane ySplit="${freeze - 1}" topLeftCell="A${freeze}" activePane="bottomLeft" state="frozen"/>` : ''}</sheetView></sheetViews>` +
  `<sheetFormatPr defaultRowHeight="15"/><cols>${cols.map((w, i) => `<col min="${i + 1}" max="${i + 1}" width="${w}" customWidth="1"/>`).join('')}</cols>` +
  `<sheetData>${rows.map(([r, cells, ht]) => `<row r="${r}"${ht ? ` ht="${ht}" customHeight="1"` : ''}>${cells.join('')}</row>`).join('')}</sheetData>` +
  (filter ? `<autoFilter ref="${filter}"/>` : '') +
  (merges.length ? `<mergeCells count="${merges.length}">${merges.map(m => `<mergeCell ref="${m}"/>`).join('')}</mergeCells>` : '') + cf +
  `<pageMargins left="0.5" right="0.5" top="0.75" bottom="0.75" header="0.3" footer="0.3"/><pageSetup orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>`;

// ---------- unique, Excel-safe tab names ----------
const taken = new Set(['summary']);
const tabName = raw => {
  let base = String(raw || 'Quote').replace(/[\[\]:*?\/\\']/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 31) || 'Quote';
  let name = base, n = 2;
  while (taken.has(name.toLowerCase())) { const sfx = ` (${n++})`; name = base.slice(0, 31 - sfx.length) + sfx; }
  taken.add(name.toLowerCase()); return name;
};
const qref = name => `'${name.replace(/'/g, "''")}'`;

// ---------- one tab per quote ----------
const quoteSheets = p.quotes.map(q => {
  const name = tabName([q.vendor, q.quote_number].filter(Boolean).join(' '));
  const H = ['Tag', 'Qty', 'Description', `Unit Price (${CUR})`, `Extended (${CUR})`, 'Lead Time'];
  const rows = [
    [1, [cStr('A1', [q.vendor, q.quote_number].filter(Boolean).join(' — '), S.title)], 22],
    [2, [cStr('A2', [q.quote_date ? `Quote date: ${q.quote_date}` : '', q.file_name ? `Source: ${q.file_name}` : ''].filter(Boolean).join('   ·   '), S.sub)]],
    [4, H.map((h, i) => cStr(`${col(i)}4`, h, S.head)), 20],
  ];
  let r = 5, sum = 0;
  for (const l of q.lines) {
    const qty = num(l.qty), unit = num(l.unit_price), ext = r2((qty || 0) * (unit || 0)); sum += ext;
    rows.push([r, [cStr(`A${r}`, l.tag || '', S.text), cNum(`B${r}`, qty, S.qty), cStr(`C${r}`, l.description || '', S.wrap),
      cNum(`D${r}`, unit, S.money), cF(`E${r}`, `B${r}*D${r}`, ext, S.money), cStr(`F${r}`, l.lead_time || '', S.text)]]);
    r++;
  }
  const last = r - 1, totRow = r;
  rows.push([totRow, [cStr(`A${totRow}`, 'Total', S.totLabel), cStr(`B${totRow}`, '', S.totLabel), cStr(`C${totRow}`, '', S.totLabel),
    cStr(`D${totRow}`, '', S.totLabel), cF(`E${totRow}`, `SUM(E5:E${last})`, r2(sum), S.totMoney), cStr(`F${totRow}`, '', S.totLabel)], 18]);
  let rr = totRow + 2;
  for (const n of q.not_quoted || []) { rows.push([rr, [cStr(`A${rr}`, `Not quoted: ${n}`, S.sub)]]); rr++; }
  if (q.notes) rows.push([rr, [cStr(`A${rr}`, `Notes: ${q.notes}`, S.sub)]]);
  return { name, sum: r2(sum), totRow, q, xml: sheetXml({ cols: [14, 7, 70, 16, 16, 18], rows, merges: ['A1:F1', 'A2:F2'], freeze: 5, filter: `A4:F${last}` }) };
});

// ---------- Summary tab ----------
const SH = ['Vendor', 'Quote #', 'Quote Date', 'Lines', `Lines Total (${CUR})`, `Quote Subtotal (${CUR})`, 'Check'];
const srows = [
  [1, [cStr('A1', p.jobName || 'Vendor Quotes', S.title)], 22],
  [2, [cStr('A2', `${quoteSheets.length} quote(s) · built ${new Date().toISOString().slice(0, 10)} · Lines Total = sum of each quote tab; Check compares it to the subtotal printed on the quote`, S.sub)]],
  [4, SH.map((h, i) => cStr(`${col(i)}4`, h, S.head)), 20],
];
let sr = 5;
for (const s of quoteSheets) {
  const st = num(s.q.quote_subtotal);
  const chk = st === null ? 'No subtotal' : (Math.abs(s.sum - st) < 0.02 ? 'OK' : 'CHECK');
  srows.push([sr, [cStr(`A${sr}`, s.q.vendor || '', S.text), cStr(`B${sr}`, s.q.quote_number || '', S.text), cStr(`C${sr}`, s.q.quote_date || '', S.text),
    cNum(`D${sr}`, s.q.lines.length, S.qty), cF(`E${sr}`, `${qref(s.name)}!E${s.totRow}`, s.sum, S.money), cNum(`F${sr}`, st, S.money),
    cF(`G${sr}`, `IF(F${sr}="","No subtotal",IF(ABS(E${sr}-F${sr})<0.02,"OK","CHECK"))`, chk, S.check, true)]]);
  sr++;
}
const sLast = sr - 1;
srows.push([sr, [cStr(`A${sr}`, 'All quotes', S.totLabel), ...['B', 'C'].map(c => cStr(`${c}${sr}`, '', S.totLabel)),
  cF(`D${sr}`, `SUM(D5:D${sLast})`, quoteSheets.reduce((a, s) => a + s.q.lines.length, 0), S.totLabel),
  cF(`E${sr}`, `SUM(E5:E${sLast})`, r2(quoteSheets.reduce((a, s) => a + s.sum, 0)), S.totMoney),
  cStr(`F${sr}`, '', S.totLabel), cStr(`G${sr}`, '', S.totLabel)], 18]);
const cfXml = `<conditionalFormatting sqref="G5:G${sLast}"><cfRule type="cellIs" dxfId="0" priority="1" operator="equal"><formula>"CHECK"</formula></cfRule><cfRule type="cellIs" dxfId="1" priority="2" operator="equal"><formula>"OK"</formula></cfRule></conditionalFormatting>`;
// ---------- Comparison tab (only when Match Items Across Quotes ran) ----------
let compSheet = null;
if (p.comparison) {
  const cmp = p.comparison, n = cmp.quoteNames.length, first = 5, last = first + cmp.items.length - 1;
  const pc = i => col(3 + i);                                   // unit-price columns D, E, F…
  const P0 = pc(0), Pn = pc(n - 1), LOW = col(3 + n), BEST = col(4 + n), SPR = col(5 + n), lc = i => col(6 + n + i);
  const LAST = lc(n - 1);
  const H = ['Item', 'Description', 'Qty', ...cmp.quoteNames, `Lowest Unit (${CUR})`, 'Best Quote', 'Spread', ...cmp.quoteNames.map(q => `Lead time · ${q}`)];
  const rows = [
    [1, [cStr('A1', `Quote comparison — ${p.jobName || 'Vendor Quotes'}`, S.title)], 22],
    [2, [cStr('A2', `Unit prices (${CUR}) side by side · green = lowest price for the item · ties are marked and not counted · Spread = highest vs lowest · blank = not quoted`, S.sub)]],
    [4, H.map((h, i) => cStr(`${col(i)}4`, h, S.head)), 44],
  ];
  cmp.items.forEach((it, k) => {
    const r = first + k, rng = `${P0}${r}:${Pn}${r}`;
    rows.push([r, [
      cStr(`A${r}`, it.label, S.text), cStr(`B${r}`, it.description, S.wrap), cNum(`C${r}`, num(it.qty), S.qty),
      ...it.prices.map((v, i) => cNum(`${pc(i)}${r}`, num(v), S.money)),
      cF(`${LOW}${r}`, `MIN(${rng})`, it.lowest, S.money),
      cF(`${BEST}${r}`, `INDEX($${P0}$4:$${Pn}$4,MATCH(${LOW}${r},${rng},0))&IF(COUNTIF(${rng},${LOW}${r})>1," (tie)","")`, it.bestQuote, S.text, true),
      it.spread === null ? cF(`${SPR}${r}`, `IF(COUNT(${rng})<2,"",MAX(${rng})/MIN(${rng})-1)`, '', S.pct, true)
                         : cF(`${SPR}${r}`, `IF(COUNT(${rng})<2,"",MAX(${rng})/MIN(${rng})-1)`, it.spread, S.pct),
      ...it.leads.map((v, i) => cStr(`${lc(i)}${r}`, v, S.text)),
    ]]);
  });
  const t1 = last + 1, t2 = last + 2, t3 = last + 3;
  const blankTo = (r, fromIdx, toIdx) => Array.from({ length: toIdx - fromIdx + 1 }, (_, j) => cStr(`${col(fromIdx + j)}${r}`, '', S.totLabel));
  rows.push([t1, [cStr(`A${t1}`, 'Total at these quantities', S.totLabel), ...blankTo(t1, 1, 2),
    ...cmp.totals.map((t, i) => cF(`${pc(i)}${t1}`, `SUMPRODUCT($C$${first}:$C$${last},${pc(i)}${first}:${pc(i)}${last})`, t.total, S.totMoney)),
    cF(`${LOW}${t1}`, `SUMPRODUCT($C$${first}:$C$${last},${LOW}${first}:${LOW}${last})`, cmp.bestMix, S.totMoney),
    cStr(`${BEST}${t1}`, '← best mix (lowest price on every item)', S.totLabel), ...blankTo(t1, 5 + n, 5 + 2 * n)], 18]);
  rows.push([t2, [cStr(`A${t2}`, 'Items quoted', S.totLabel), ...blankTo(t2, 1, 2),
    ...cmp.totals.map((t, i) => cF(`${pc(i)}${t2}`, `COUNT(${pc(i)}${first}:${pc(i)}${last})&" of ${cmp.itemCount}"`, `${t.itemsQuoted} of ${cmp.itemCount}`, S.check, true)),
    ...blankTo(t2, 3 + n, 5 + 2 * n)]]);
  rows.push([t3, [cStr(`A${t3}`, 'Lowest price on', S.totLabel), ...blankTo(t3, 1, 2),
    ...cmp.totals.map((t, i) => cF(`${pc(i)}${t3}`, `COUNTIF($${BEST}$${first}:$${BEST}$${last},${pc(i)}$4)&" item(s)"`, `${t.lowestOn} item(s)`, S.check, true)),
    ...blankTo(t3, 3 + n, 5 + 2 * n)]]);
  const cf = `<conditionalFormatting sqref="${P0}${first}:${Pn}${last}"><cfRule type="expression" dxfId="1" priority="1"><formula>AND(ISNUMBER(${P0}${first}),${P0}${first}=MIN($${P0}${first}:$${Pn}${first}))</formula></cfRule></conditionalFormatting>`;
  compSheet = { name: 'Comparison', xml: sheetXml({ cols: [14, 46, 7, ...Array(n).fill(16), 16, 32, 9, ...Array(n).fill(20)], rows,
    merges: [`A1:${LAST}1`, `A2:${LAST}2`], freeze: 5, cf }) };
}
taken.add('comparison');
const sheets = [{ name: 'Summary', xml: sheetXml({ cols: [26, 16, 14, 8, 18, 20, 14], rows: srows, merges: ['A1:G1', 'A2:G2'], freeze: 5, cf: cfXml }) },
  ...(compSheet ? [compSheet] : []), ...quoteSheets];


// ---------- package parts ----------
const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">` +
  `<numFmts count="3"><numFmt numFmtId="164" formatCode="#,##0.00"/><numFmt numFmtId="165" formatCode="#,##0.##"/><numFmt numFmtId="166" formatCode="0.0%"/></numFmts>` +
  `<fonts count="5"><font><sz val="10"/><name val="Arial"/></font><font><b/><sz val="14"/><color rgb="FF1F497D"/><name val="Arial"/></font>` +
  `<font><i/><sz val="9"/><color rgb="FF666666"/><name val="Arial"/></font><font><b/><sz val="10"/><color rgb="FFFFFFFF"/><name val="Arial"/></font><font><b/><sz val="10"/><name val="Arial"/></font></fonts>` +
  `<fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill>` +
  `<fill><patternFill patternType="solid"><fgColor rgb="FF1F497D"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFDCE6F1"/></patternFill></fill></fills>` +
  `<borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style="thin"><color rgb="FFBFBFBF"/></left><right style="thin"><color rgb="FFBFBFBF"/></right><top style="thin"><color rgb="FFBFBFBF"/></top><bottom style="thin"><color rgb="FFBFBFBF"/></bottom><diagonal/></border></borders>` +
  `<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="12">` +
  `<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>` +                                                       // 0 default
  `<xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/>` +                                         // 1 title
  `<xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0" applyFont="1"/>` +                                         // 2 sub
  `<xf numFmtId="0" fontId="3" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf>` + // 3 header
  `<xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment vertical="top"/></xf>` + // 4 text
  `<xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf>` + // 5 wrap
  `<xf numFmtId="165" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="top"/></xf>` + // 6 qty
  `<xf numFmtId="164" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1" applyAlignment="1"><alignment vertical="top"/></xf>` + // 7 money
  `<xf numFmtId="0" fontId="4" fillId="3" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1"/>` +          // 8 total label
  `<xf numFmtId="164" fontId="4" fillId="3" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/>` + // 9 total money
  `<xf numFmtId="0" fontId="4" fillId="0" borderId="1" xfId="0" applyFont="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="top"/></xf>` + // 10 check
  `<xf numFmtId="166" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="top"/></xf>` + // 11 percent
  `</cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>` +
  `<dxfs count="2"><dxf><font><b/><color rgb="FFC00000"/></font><fill><patternFill><bgColor rgb="FFFFC7CE"/></patternFill></fill></dxf><dxf><font><color rgb="FF006100"/></font><fill><patternFill><bgColor rgb="FFC6EFCE"/></patternFill></fill></dxf></dxfs></styleSheet>`;
const files = {
  '[Content_Types].xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets.map((s, i) => `<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`,
  '_rels/.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`,
  'xl/workbook.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><bookViews><workbookView/></bookViews><sheets>${sheets.map((s, i) => `<sheet name="${esc(s.name)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>`).join('')}</sheets>${quoteSheets.length ? `<definedNames>${quoteSheets.map(s => `<definedName name="_xlnm._FilterDatabase" localSheetId="${sheets.indexOf(s)}" hidden="1">${esc(qref(s.name))}!$A$4:$F$${s.totRow - 1}</definedName>`).join('')}</definedNames>` : ''}<calcPr calcId="191029" fullCalcOnLoad="1"/></workbook>`,
  'xl/_rels/workbook.xml.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((s, i) => `<Relationship Id="rId${i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join('')}<Relationship Id="rId${sheets.length + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`,
  'xl/styles.xml': styles,
};
sheets.forEach((s, i) => { files[`xl/worksheets/sheet${i + 1}.xml`] = s.xml; });

// ---------- minimal ZIP writer (stored entries + CRC32) ----------
const crcTable = Array.from({ length: 256 }, (_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
const crc32 = buf => { let c = 0xFFFFFFFF; for (const b of buf) c = crcTable[(c ^ b) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
const locals = [], centrals = []; let offset = 0;
for (const [name, text] of Object.entries(files)) {
  const nameBuf = Buffer.from(name, 'utf8'), data = Buffer.from(text, 'utf8'), crc = crc32(data);
  const lh = Buffer.alloc(30); lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0x0800, 6); lh.writeUInt16LE(0, 8);
  lh.writeUInt16LE(0, 10); lh.writeUInt16LE(0x21, 12); lh.writeUInt32LE(crc, 14); lh.writeUInt32LE(data.length, 18); lh.writeUInt32LE(data.length, 22);
  lh.writeUInt16LE(nameBuf.length, 26); lh.writeUInt16LE(0, 28);
  const ch = Buffer.alloc(46); ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6); ch.writeUInt16LE(0x0800, 8); ch.writeUInt16LE(0, 10);
  ch.writeUInt16LE(0, 12); ch.writeUInt16LE(0x21, 14); ch.writeUInt32LE(crc, 16); ch.writeUInt32LE(data.length, 20); ch.writeUInt32LE(data.length, 24);
  ch.writeUInt16LE(nameBuf.length, 28); ch.writeUInt32LE(offset, 42);
  locals.push(lh, nameBuf, data); centrals.push(ch, nameBuf);
  offset += 30 + nameBuf.length + data.length;
}
const cd = Buffer.concat(centrals), end = Buffer.alloc(22);
end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(Object.keys(files).length, 8); end.writeUInt16LE(Object.keys(files).length, 10);
end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(offset, 16);
const xlsx = Buffer.concat([...locals, cd, end]);

const bin = await this.helpers.prepareBinaryData(xlsx, 'quote-lines.xlsx', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
return [{ json: { tabs: sheets.map(s => s.name), comparison: p.comparison || null }, binary: { data: bin } }];

// Builds the HTML summary for the reply and keeps the spreadsheet attached.
const p = $('Parse Claude Quote Lines').first().json;
const cfg = $('Set Email Processing Config').first().json;
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const cur = String(cfg.currency || 'USD');
const money = n => (n == null || n === '') ? '' : Number(n).toLocaleString('en-US', { style: 'currency', currency: cur });
const th = 'style="background:#1F497D;color:#fff;padding:4px 8px;text-align:left;font-size:12px"';
const td = 'style="border-bottom:1px solid #ddd;padding:4px 8px;font-size:12px;vertical-align:top"';
const tdr = 'style="border-bottom:1px solid #ddd;padding:4px 8px;font-size:12px;text-align:right;vertical-align:top"';

const checkRows = p.checks.map(c => {
  const v = c.match === null ? '<span style="color:#9a6700">no subtotal printed — check manually</span>'
    : c.match ? '<span style="color:#1a7f37">✔ matches the quote subtotal</span>'
    : `<b style="color:#cf222e">✘ lines total ${money(c.sum)} vs quote subtotal ${money(c.subtotal)} — CHECK</b>`;
  return `<li>${esc(c.vendor)} ${esc(c.quote)}: ${c.lines} line(s), ${money(c.sum)} — ${v}</li>`;
}).join('');
const rows = p.rows.map(r => `<tr><td ${td}>${esc(r['Vendor'])}</td><td ${td}>${esc(r['Quote #'])}</td><td ${tdr}>${esc(r['Qty'])}</td><td ${td}>${esc(r['Description'])}</td><td ${tdr}>${money(r['Unit Price'])}</td><td ${tdr}>${money(r['Extended'])}</td><td ${td}>${esc(r['Lead Time'])}</td></tr>`).join('');
const extra = [];
if (p.notQuoted.length) extra.push(`<p><b>Not quoted / no price:</b></p><ul>${p.notQuoted.map(n => `<li>${esc(n)}</li>`).join('')}</ul>`);
if (p.notes.length) extra.push(`<p><b>Notes from the quote:</b></p><ul>${p.notes.map(n => `<li>${esc(n)}</li>`).join('')}</ul>`);
const cmp = $input.first().json.comparison;
const cmpHtml = !cmp ? '' : `<p><b>Quote comparison</b>: ${cmp.itemCount} item(s), ${cmp.sharedItems} quoted by more than one vendor (see the Comparison tab)</p><ul>${
  cmp.totals.map(t => `<li>${esc(t.name)}: ${t.itemsQuoted} of ${cmp.itemCount} items, ${money(t.total)}, lowest price on ${t.lowestOn} item(s)</li>`).join('')}</ul>
<p>Best mix (lowest price on every item): <b>${money(cmp.bestMix)}</b> · Cheapest complete quote: ${cmp.cheapestComplete ? `<b>${esc(cmp.cheapestComplete.name)}</b> ${money(cmp.cheapestComplete.total)}` : 'none of the quotes covers every item'}</p>`;

const mismatch = p.checks.some(c => c.match === false);

const html = `<div style="font-family:Arial,sans-serif;font-size:13px">
${mismatch ? '<p style="color:#cf222e"><b>⚠ CHECK TOTALS: at least one quote does not add up to its printed subtotal.</b></p>' : ''}
<p>Extracted <b>${p.rows.length}</b> line(s) from <b>${p.checks.length}</b> quote(s). The spreadsheet is attached.</p>
<p><b>Totals check</b></p><ul>${checkRows}</ul>
${cmpHtml}
<table style="border-collapse:collapse"><tr><th ${th}>Vendor</th><th ${th}>Quote #</th><th ${th}>Qty</th><th ${th}>Description</th><th ${th}>Unit</th><th ${th}>Ext</th><th ${th}>Lead time</th></tr>${rows}</table>
${extra.join('\n')}</div>`;

const item = $input.first();
item.binary.data.fileName = `Quote Lines - ${p.jobName.replace(/[\\/:*?"<>|]+/g, ' ').trim().slice(0, 80) || 'Vendor Quote'}.xlsx`;
return [{ json: { html }, binary: item.binary }];

// Explains to the sender why no spreadsheet was produced.
const g = $('Loop Over Each Quote Email').first().json;
const j = $input.first().json;
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
let reason;
if (j.status === 'no_pdf') reason = 'No PDF attachment was found. Attach the vendor quote as a PDF and send it again.';
else if (j.status === 'no_lines') reason = j.error;
else {
  const e = j.error;
  reason = typeof e === 'string' ? e : ([e?.message, e?.description].filter(Boolean).join(' — ') || JSON.stringify(e || j).slice(0, 800));
}
return [{ json: { html: `<div style="font-family:Arial,sans-serif;font-size:13px"><p>Sorry, I couldn't build a spreadsheet from <b>${esc(g.pdfNames.join(', ') || 'this email')}</b>.</p><p><b>Reason:</b> ${esc(reason)}</p></div>` } }];

// Lines up the same item across several quotes (Claude gives equivalent items the same item_key)
// and works out the lowest price per item, the best-mix total and the cheapest complete quote.
const p = $input.first().json;
const norm = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]+/g, '');
const r2 = n => Math.round(n * 100) / 100;

const quoteNames = [];
const seen = new Set();
for (const q of p.quotes) {               // short unique column names, e.g. "Acme Valve Q-7781"
  let base = [q.vendor, q.quote_number].filter(Boolean).join(' ') || 'Quote';
  let name = base, n = 2;
  while (seen.has(name.toLowerCase())) name = `${base} (${n++})`;
  seen.add(name.toLowerCase()); quoteNames.push(name);
}

const items = new Map();                  // key -> { label, description, qty, prices[], leads[] }
p.quotes.forEach((q, qi) => {
  const usedInThisQuote = new Map();
  for (const l of q.lines) {
    let key = norm(l.item_key || l.tag || l.part_number || l.description);
    const dup = (usedInThisQuote.get(key) || 0) + 1;      // same key twice in one quote -> keep separate
    usedInThisQuote.set(key, dup);
    if (dup > 1) key = `${key}#${dup}`;
    if (!items.has(key)) items.set(key, { key, label: l.item_key || l.tag || l.part_number || '', description: l.description || '',
      qty: Number(l.qty) || 0, prices: Array(p.quotes.length).fill(null), leads: Array(p.quotes.length).fill('') });
    const it = items.get(key);
    it.prices[qi] = Number(l.unit_price);
    it.leads[qi] = l.lead_time || '';
  }
});

const list = [...items.values()];
const shared = list.filter(it => it.prices.filter(v => v !== null).length >= 2).length;
if (!shared) return [{ json: { ...p, comparison: null } }];   // nothing in common -> no comparison tab

let bestMix = 0;
const lowestCount = Array(p.quotes.length).fill(0);
for (const it of list) {
  const priced = it.prices.map((v, i) => [v, i]).filter(([v]) => v !== null);
  const [minV, minI] = priced.reduce((a, b) => (b[0] < a[0] ? b : a));
  const tie = priced.filter(([v]) => Math.abs(v - minV) < 0.005).length > 1;
  it.lowest = minV; it.bestQuote = quoteNames[minI] + (tie ? ' (tie)' : '');
  it.spread = priced.length > 1 ? Math.max(...priced.map(x => x[0])) / minV - 1 : null;
  bestMix += it.qty * minV;
  if (!tie) lowestCount[minI]++;
}
const totals = quoteNames.map((name, qi) => ({
  name, itemsQuoted: list.filter(it => it.prices[qi] !== null).length,
  total: r2(list.reduce((a, it) => a + (it.prices[qi] !== null ? it.qty * it.prices[qi] : 0), 0)),
  lowestOn: lowestCount[qi],
}));
const complete = totals.filter(t => t.itemsQuoted === list.length).sort((a, b) => a.total - b.total);

return [{ json: { ...p, comparison: {
  quoteNames, items: list, totals, itemCount: list.length, sharedItems: shared,
  bestMix: r2(bestMix), cheapestComplete: complete[0] || null,
} } }];
